"""Renders CHECKPOINT.md from the stored catalog_csb data (stdlib only; needs `psql`; READ-ONLY).

    export PGHOST=127.0.0.1 PGPORT=<port> PGUSER=<role that can read> PGDATABASE=<database>
    python3 -I data/csb-research/render_checkpoint.py > data/csb-research/CHECKPOINT.md

Course-level facts only: course codes, section COUNTS, statuses and open items. No CRN, instructor name, meeting time or page text, so the output
may be committed (the underlying Banner data may not be).
"""
import json
import subprocess
import sys


def rows(sql):
    r = subprocess.run(["psql", "-X", "-q", "-v", "ON_ERROR_STOP=1", "-At", "-c", f"SELECT COALESCE(json_agg(t), '[]'::json) FROM ({sql}) t"], capture_output=True, text=True, timeout=300)
    if r.returncode != 0:
        sys.exit("psql failed: " + (r.stdout + r.stderr).strip()[:400])
    return json.loads(r.stdout.strip())


def table(header, body):
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    out += ["| " + " | ".join(str(c) for c in row) + " |" for row in body]
    return "\n".join(out)


def main():
    p = print
    meta = rows("SELECT (SELECT max(imported_at)::date::text FROM catalog_csb.import_run) AS last_import, (SELECT count(*) FROM catalog_csb.section) AS sections, (SELECT count(*) FROM catalog_csb.offering) AS offerings, "
                "(SELECT count(*) FROM catalog_csb.catalog_course) AS courses, (SELECT count(DISTINCT instructor_name) FROM catalog_csb.section_instructor WHERE NOT is_placeholder) AS names, "
                "(SELECT count(*) FROM catalog_csb.section_instructor WHERE is_placeholder) AS placeholders")[0]
    p("# CSB research checkpoint (generated)\n")
    p("Generated by `render_checkpoint.py` from `catalog_csb`. Course-level counts and statuses only; the Banner data itself (CRNs, instructors, times, page text) is local-only and never committed.\n")
    p(f"Stored: **{meta['sections']} sections** in **{meta['offerings']} offerings**, **{meta['courses']} catalog course identities**, {meta['names']} distinct named instructors and {meta['placeholders']} placeholder entries. Last import: {meta['last_import']}.\n")
    p("Panels inspected for every stored section: Class Details, Attributes, Restrictions, Prerequisites, Corequisites, Cross Listed Courses, Linked Sections. Panels never opened: Enrollment/Waitlist (seat counts are never stored), Instructor/Meeting Times (instructors were read from the results grid), Fees, Bookstore, Course Description (the public catalog was used).\n")

    p("## 1. Required CSB courses (every exact course and alternative the catalog names)\n")
    inv = rows("""WITH req AS (SELECT DISTINCT o.course_id, g.group_key, g.logic FROM catalog_csb.requirement_option o JOIN catalog_csb.requirement_group g USING (group_id) WHERE o.course_id IS NOT NULL),
		research AS (SELECT o.course_id, count(*) AS n, string_agg(DISTINCT t.tier, ',') AS tier FROM catalog_research.offering o JOIN catalog_research.section s USING (term_code, offering_id)
			JOIN catalog_research.offering_tier t ON t.term_code = o.term_code AND t.offering_id = o.offering_id GROUP BY o.course_id)
		SELECT r.group_key, r.course_id, cov.coverage, COALESCE(s.n, rs.n, 0) AS sections, rs.tier AS research_tier
		FROM req r JOIN catalog_csb.course_coverage cov ON cov.course_id = r.course_id
		LEFT JOIN (SELECT offering_id AS course_id, count(*) AS n FROM catalog_csb.section GROUP BY 1) s ON s.course_id = r.course_id LEFT JOIN research rs ON rs.course_id = r.course_id
		ORDER BY r.group_key COLLATE \"C\", r.course_id COLLATE \"C\"""")
    label = {"CSB_RESEARCH_OFFERED": "new: researched here, offered", "IN_CATALOG_RESEARCH_OFFERED": "already in catalog_research (not touched)",
             "CSB_RESEARCH_SEARCHED_NOT_OFFERED": "searched: NOT_OFFERED_IN_SPRING_2027", "NOT_SEARCHED_ANYWHERE": "NOT SEARCHED anywhere: gap for the catalog_research owner"}
    p(table(["Requirement", "Course", "Status", "Spring 2027 sections", "Tier in catalog_research"], [(r["group_key"], r["course_id"], label.get(r["coverage"], r["coverage"]), r["sections"], r["research_tier"] or "") for r in inv]))
    counts = {}
    for r in inv:
        counts[r["coverage"]] = counts.get(r["coverage"], 0) + 1
    p("\nTotals: " + ", ".join(f"{label.get(k, k)}: {v}" for k, v in sorted(counts.items())) + f" (of {len(inv)} course identities).\n")

    p("## 2. Newly researched courses and what Banner showed\n")
    detail = rows("""SELECT o.offering_id, o.title_short, o.sections, o.lectures, o.components, o.named, o.placeholders, o.restriction_variants, o.prereq_variants, o.cmp, o.links, o.credit_flag, o.xl
		FROM (SELECT o.offering_id, left(o.title, 38) AS title_short,
			(SELECT count(*) FROM catalog_csb.section s WHERE s.offering_id = o.offering_id) AS sections,
			(SELECT count(*) FROM catalog_csb.section s WHERE s.offering_id = o.offering_id AND s.component_type = 'LECTURE') AS lectures,
			(SELECT string_agg(DISTINCT s.component_type COLLATE \"C\", '+' ORDER BY s.component_type COLLATE \"C\") FROM catalog_csb.section s WHERE s.offering_id = o.offering_id) AS components,
			(SELECT count(DISTINCT i.instructor_name) FROM catalog_csb.section_instructor i JOIN catalog_csb.section s USING (term_code, crn) WHERE s.offering_id = o.offering_id AND NOT i.is_placeholder) AS named,
			(SELECT count(*) FROM catalog_csb.section_instructor i JOIN catalog_csb.section s USING (term_code, crn) WHERE s.offering_id = o.offering_id AND i.is_placeholder) AS placeholders,
			(SELECT max(v.distinct_restriction_texts) FROM catalog_csb.offering_requirement_variant v WHERE v.offering_id = o.offering_id) AS restriction_variants,
			(SELECT max(v.distinct_prerequisite_texts) FROM catalog_csb.offering_requirement_variant v WHERE v.offering_id = o.offering_id) AS prereq_variants,
			(SELECT string_agg(DISTINCT c.status, '/') FROM catalog_csb.prerequisite_comparison c WHERE c.course_id = o.offering_id) AS cmp,
			(SELECT string_agg(DISTINCT cr.registration_shape, '; ') FROM catalog_csb.component_requirement cr WHERE cr.offering_id = o.offering_id AND cr.component_type = 'LECTURE') AS links,
			(SELECT count(*) FILTER (WHERE s.credits_display_status = 'DETAILS_DIFFER_FROM_GRID') FROM catalog_csb.section s WHERE s.offering_id = o.offering_id) AS credit_flag,
			(SELECT count(*) FROM catalog_csb.section_cross_list x JOIN catalog_csb.section s USING (term_code, crn) WHERE s.offering_id = o.offering_id) AS xl
			FROM catalog_csb.offering o) o ORDER BY o.offering_id COLLATE \"C\"""")
    p(table(["Course", "Title", "Sections", "Lectures", "Components", "Named instructors", "Placeholders", "Restriction variants", "Prerequisite variants", "Catalog vs Banner prerequisite", "Linked options", "Sections whose Class Details credits differ from the grid", "Cross-list rows"],
            [(d["offering_id"], d["title_short"], d["sections"], d["lectures"], d["components"], d["named"], d["placeholders"], d["restriction_variants"], d["prereq_variants"], d["cmp"] or "", d["links"] or "none listed", d["credit_flag"], d["xl"]) for d in detail]))
    p("\nA course whose sections show more than one restriction or prerequisite variant is NOT assumed uniform: the variants are stored per section.\n")

    p("## 3. Searched with no Spring 2027 sections (exact subject and course number)\n")
    zero = rows("SELECT subject_label, course_number, course_id FROM catalog_csb.banner_search WHERE search_kind = 'EXACT_COURSE' AND result = 'NOT_OFFERED' ORDER BY subject_label COLLATE \"C\", course_number COLLATE \"C\"")
    p(", ".join(f"{z['course_id'] or z['subject_label'] + ' ' + z['course_number']}" for z in zero) + f"  ({len(zero)} searches, each recorded as `NOT_OFFERED_IN_SPRING_2027`; a cross-listing under another subject was not checked).\n")

    p("## 4. Natural-science sequences (suggested, not required)\n")
    seq = rows("""SELECT s.sequence_key, s.listed_credits_text, s.status, array_to_string(s.course_availability, ' ') AS courses FROM catalog_csb.ns_sequence_status s ORDER BY s.sequence_key COLLATE \"C\"""")
    p(table(["Sequence", "Listed credits", "This term", "Course availability"], [(s["sequence_key"], s["listed_credits_text"], s["status"], s["courses"]) for s in seq]))
    dep = rows("SELECT sequence_key, course_id, dependency_status, array_to_string(other_courses_named, ' ') AS others FROM catalog_csb.ns_sequence_dependency WHERE dependency_status NOT IN ('SATISFIED_BY_EARLIER_COURSES_ALONE') ORDER BY sequence_key COLLATE \"C\", course_id COLLATE \"C\"")
    p("\nPrerequisite dependencies the catalog adds to a sequence (a sequence is only a suggestion; these are what it still needs):\n")
    p(table(["Sequence", "Course", "Catalog dependency", "Other courses named"], [(d["sequence_key"], d["course_id"], d["dependency_status"], d["others"]) for d in dep]))

    p("\n## 5. Professional-elective candidates\n")
    p("Every professional-elective candidate is `APPROVAL_NOT_VERIFIED`: neither the catalog nor csb.lehigh.edu publishes a closed approved list (the co-directors approve). Only the 36 entries of the catalog's CSE elective list are `CATALOG_LISTED`.\n")
    cand = rows("""SELECT m.course_id, string_agg(DISTINCT m.member_group || CASE WHEN m.track <> '' THEN ':' || m.track ELSE '' END, '; ') AS basis,
			GREATEST((SELECT count(*) FROM catalog_csb.section s WHERE s.offering_id = m.course_id),
				(SELECT count(*) FROM catalog_research.section s JOIN catalog_research.offering o USING (term_code, offering_id) WHERE o.course_id = m.course_id)) AS sections, cov.coverage
		FROM catalog_csb.elective_list_member m JOIN catalog_csb.course_coverage cov ON cov.course_id = m.course_id
		WHERE m.list_key = 'CSB_PROFESSIONAL_ELECTIVES' AND m.member_group <> 'CSE_APPROVED_LIST_COURSES' GROUP BY m.course_id, cov.coverage ORDER BY m.course_id COLLATE \"C\"""")
    p(table(["Course", "Why it is a candidate", "Spring 2027 sections", "Coverage"], [(c["course_id"], c["basis"], c["sections"], label.get(c["coverage"], c["coverage"])) for c in cand]))

    p("\n## 6. CSE courses named by the CSB degree that no one has searched in Banner\n")
    p("Reported to the owner of the CSE catalog research instead of being collected here.\n")
    gap = rows("SELECT course_id FROM catalog_csb.course_coverage WHERE coverage = 'NOT_SEARCHED_ANYWHERE' AND course_id LIKE 'CSE-%' ORDER BY course_id COLLATE \"C\"")
    p(", ".join(g["course_id"] for g in gap) + f"  ({len(gap)} courses).\n")

    p("## 7. Open items and unresolved data\n")
    for u in rows("SELECT source, subject, detail FROM catalog_csb.unresolved_item ORDER BY item_id"):
        if u["source"] != "BANNER_CROSS_LIST_PANEL":
            p(f"- **{u['subject']}** ({u['source']}): {u['detail']}")
    xl = rows("SELECT count(*) AS n FROM catalog_csb.unresolved_item WHERE source = 'BANNER_CROSS_LIST_PANEL'")[0]["n"]
    p(f"- **Cross-listed sections not collected** ({xl} listings): the Cross Listed Courses panel names a partner section under another subject (for example graduate-level or PHY 019 sections); the partner's own details are NOT_COLLECTED.")
    for c in rows("SELECT conflict_key, status FROM catalog_csb.source_conflict ORDER BY conflict_key COLLATE \"C\""):
        p(f"- **Source conflict** `{c['conflict_key']}`: {c['status']}")


if __name__ == "__main__":
    main()
